if (!admin()): ?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><link rel="stylesheet" href="style.css"><title>כניסה</title></head><body class="login"><form method="post"><h1>כניסה פרטית</h1><input type="hidden" name="csrf" value="<?=csrf()?>"><label>שם משתמש<input name="user" required autocomplete="username"></label><label>סיסמה<input name="password" type="password" required autocomplete="current-password"></label><button class="button">כניסה</button><?php if(isset($error)): ?><p class="error"><?=e($error)?></p><?php endif ?></form></body></html><?php exit; endif;
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); if (isset($_POST['request_id'])) $pdo->prepare('UPDATE requests SET status="handled" WHERE id=?')->execute([(int)$_POST['request_id']]); if (isset($_FILES['file'])&&$_FILES['file']['error']===UPLOAD_ERR_OK) { $f=$_FILES['file']; $allowed=['application/pdf'=>'pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','image/jpeg'=>'jpg','image/png'=>'png']; $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); if($f['size']<=26214400&&isset($allowed[$mime])) { $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$name); $pdo->prepare('INSERT INTO summaries(title,subject,grade,description,file_name,published) VALUES(?,?,?,?,?,1)')->execute([trim($_POST['title']),trim($_POST['subject']),trim($_POST['grade']),trim($_POST['description']),$name]); } } header('Location: admin.php'); exit; }
$requests=$pdo->query('SELECT * FROM requests WHERE status="new" ORDER BY created_at DESC LIMIT 50')->fetchAll(); ?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="style.css"><title>ניהול</title></head><body><header><a class="brand" href="/">מחברת פתוחה</a><a href="?logout=1">יציאה</a></header><main class="admin"><h1>ניהול האתר</h1><section class="request"><div><h2>העלאת סיכום</h2></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>כותרת<input name="title" required></label><label>מקצוע<input name="subject" required></label><label>שכבה<input name="grade" required></label><label>תיאור<textarea name="description"></textarea></label><label>קובץ<input name="file" type="file" accept=".pdf,.docx,.jpg,.png" required></label><button class="button">פרסום</button></form></section><h2>בקשות חדשות</h2><?php foreach($requests as $r): ?><article class="item"><b><?=e($r['subject'])?> · <?=e($r['grade'])?></b><p><?=e($r['details'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button name="request_id" value="<?=$r['id']?>">סמן כטופל</button></form></article><?php endforeach ?></main></body></html>
